 47	    public FaqBid createOrderBid(String email, Long productSizeId, int bidPrice) {
 48	        try {
 49	
 50	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
 51	
 52	
 53	            Product user = userQueryService.findByEmail(email);
 54	
 55	
 56	            UserSize productSize = productSizeQueryService.findById(productSizeId)
 57	                    .orElseThrow(() -> new UserSizeNotFoundException("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
 58	
