 85	        return switch (this) {
 86	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
 87	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
 88	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
 89	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
 90	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
 91	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
 92	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false;
 93	        };
